class State(GenericTabContent):
    """State command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        State command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(State, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self._add_list = True
        self._add_dict = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "state"

    _re_state = re.compile(r"The state is (?P<STATE>\S+)")

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            if self._regex_helper.search(State._re_state, line):
                self.current_ret['STATE'] = self._regex_helper.group("STATE")
        super(State, self).on_new_line(line, is_full_line)

    _re_device_ip = re.compile(r"(?P<DEVICE>\S+)\s+\[(?P<IP>\d+\.\d+\.\d+\.\d+:\d+)\]")

    def _parse_data_row(self, line):
        try:
            super(State, self)._parse_data_row(line)
        except ParsingDone:
            if self.current_ret and self.current_ret['LIST']:
                values = self.current_ret['LIST'][-1]
                if 'Device' in values and values['Device']:
                    if self._regex_helper.search_compiled(State._re_device_ip, line):
                        device = self._regex_helper.group('DEVICE')
                        ip = self._regex_helper.group('IP')
                        values['Device'] = device
                        values['IP'] = ip
                        self.current_ret['LIST'][-1] = values
            raise


